#!/usr/bin/env node
// Generates the app's style data from docs/design/style-library.json (the source of truth).
//   node docs/design/tools/build-knowledge.mjs            write the generated files
//   node docs/design/tools/build-knowledge.mjs --check    exit 1 if a generated file is out of date (used by the tests)
//
// Outputs (never edit by hand):
//   app/packages/shared/src/styles.generated.ts           ids, legacy-id map, style strings, names (pipeline and brief schema)
//   app/lib/intake/knowledge/styles/library.generated.ts  full records for retrieval, recommendation and the IP alias index (server)
//   app/lib/intake/knowledge/styles/picker.generated.ts   slim records for the style picker (client-safe: no aliases, no prompts)
//   app/lib/intake/knowledge/styles/docs.generated.ts     retrieval documents (kind "style_preset") for the Greet Guide
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..", "..", "..");
const lib = JSON.parse(readFileSync(join(root, "docs", "design", "style-library.json"), "utf8"));
const check = process.argv.includes("--check");

const HEADER = "// GENERATED by docs/design/tools/build-knowledge.mjs from docs/design/style-library.json. Do not edit by hand.\n";
const j = (v) => JSON.stringify(v, null, 2);

const ids = lib.styles.map((s) => s.id);
const legacy = {};
for (const s of lib.styles) for (const l of s.legacyIds) if (!ids.includes(l)) legacy[l] = s.id;

const outputs = {};

outputs["app/packages/shared/src/styles.generated.ts"] =
  HEADER +
  `export const STYLE_IDS = ${j(ids)} as const;\nexport type StyleId = (typeof STYLE_IDS)[number];\n\n` +
  `/** Older ids (the first shared schema's six and the CMO's five presets) and the style each now resolves to. */\n` +
  `export const LEGACY_STYLE_MAP = ${j(legacy)} as const;\nexport type LegacyStyleId = keyof typeof LEGACY_STYLE_MAP;\n\n` +
  `export const STYLE_NAMES: Record<StyleId, string> = ${j(Object.fromEntries(lib.styles.map((s) => [s.id, s.name])))};\n\n` +
  `/** The image-model style strings. The IP-safety hardening lines are appended by the pipeline, not stored here. */\n` +
  `export const STYLE_STRINGS: Record<StyleId, string> = ${j(Object.fromEntries(lib.styles.map((s) => [s.id, s.styleString])))};\n`;

outputs["app/lib/intake/knowledge/styles/library.generated.ts"] =
  HEADER + `import type { StyleEntry, StyleCategory } from "./types";\n\n` +
  `export const STYLE_CATEGORIES: StyleCategory[] = ${j(lib.categories)};\n\n` +
  `export const STYLE_LIBRARY: StyleEntry[] = ${j(lib.styles)};\n`;

const slim = lib.styles.map((s) => ({
  id: s.id, name: s.name, category: s.category, status: s.status, products: s.products, ageBands: s.ageBands, occasions: s.occasions, tones: s.tones,
  description: s.description, whyThisOne: s.whyThisOne, swatches: s.swatches.map((x) => x.hex),
  consistency: { bookRating: s.consistency.bookRating, cardRating: s.consistency.cardRating }, popularity: s.popularity.rating,
  thumbnail: { file: s.thumbnail.file, rendered: s.thumbnail.rendered },
}));
outputs["app/lib/intake/knowledge/styles/picker.generated.ts"] =
  HEADER + `import type { PickerStyle, StyleCategory } from "./types";\n\n` +
  `export const PICKER_CATEGORIES: StyleCategory[] = ${j(lib.categories)};\n\n` +
  `export const PICKER_STYLES: PickerStyle[] = ${j(slim)};\n`;

// Retrieval docs. Customer-facing generic words only: franchise phrases (ipSafeAliases) are matched in code and never indexed.
const list = (a) => a.join(", ");
const docs = lib.styles.map((s) => ({
  id: `style-${s.id}`,
  kind: "style_preset",
  styleId: s.id,
  title: s.name,
  text:
    `${s.description} Looks like: ${s.look.medium}; ${s.look.technique}; ${s.look.mood}. Palette: ${s.look.palette}. ` +
    `Best for: ${list(s.bestFor)}. Not for: ${list(s.avoidFor)}. Mood: ${list(s.tones)}. For ${list(s.products)}, ages ${list(s.ageBands)}. ` +
    `Also called: ${list(s.synonyms)}. Keywords: ${list(s.tags)}. Occasions: ${list(s.occasions.map((o) => o.replaceAll("_", " ")))}.`,
  occasions: s.occasions,
  tones: s.tones,
  products: s.products,
}));
outputs["app/lib/intake/knowledge/styles/docs.generated.ts"] =
  HEADER + `import type { KbDoc } from "../types";\n\nexport const STYLE_KB_DOCS: KbDoc[] = ${j(docs)};\n`;

let stale = 0;
for (const [rel, content] of Object.entries(outputs)) {
  const p = join(root, rel);
  const same = existsSync(p) && readFileSync(p, "utf8") === content;
  if (check) {
    if (!same) { console.error(`out of date: ${rel}`); stale++; }
  } else if (!same) {
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, content, "utf8");
    console.log(`wrote ${rel}`);
  }
}
if (check && stale) process.exit(1);
if (check) console.log("generated files are up to date");
